import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App.tsx';

console.log("App Loader: Starting initialisation...");

const mountApp = () => {
  try {
    const rootElement = document.getElementById('root');
    if (!rootElement) {
      console.error("App Loader: FATAL - Could not find root element '#root'");
      return;
    }

    console.log("App Loader: Root element found. Creating React root...");
    const root = ReactDOM.createRoot(rootElement);

    console.log("App Loader: Rendering App component...");
    root.render(
      <React.StrictMode>
        <App />
      </React.StrictMode>
    );
    console.log("App Loader: Render signal sent successfully.");
  } catch (error) {
    console.error("App Loader: CRITICAL ERROR during render:", error);
    const rootElement = document.getElementById('root');
    if (rootElement) {
      rootElement.innerHTML = `
        <div style="padding: 20px; color: #e11d48; text-align: center; font-family: sans-serif;">
          <h1 style="font-size: 24px; font-weight: bold;">Launch Failed</h1>
          <p style="margin-top: 10px;">The application encountered a technical error during startup.</p>
          <pre style="text-align: left; background: #f1f5f9; padding: 15px; border-radius: 8px; font-size: 12px; margin-top: 20px; overflow: auto;">${error instanceof Error ? error.message : String(error)}</pre>
          <button onclick="window.location.reload()" style="margin-top: 20px; background: #0d9488; color: white; padding: 10px 20px; border-radius: 8px; border: none; font-weight: bold; cursor: pointer;">Retry Launch</button>
        </div>
      `;
    }
  }
};

// Start the mount process
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', mountApp);
} else {
  mountApp();
}

import React, { useState, useEffect } from 'react';
import { MedicineData, PatientProfile } from '../types';
import { checkConditionSafety } from '../services/geminiService';

interface MedicineResultProps {
  data: MedicineData;
  profile?: PatientProfile;
  isPremium: boolean;
  isPreviouslyScanned: boolean;
  overdoseWarning?: boolean;
  onOpenPremium: () => void;
  onClose: () => void;
}

const MedicineResult: React.FC<MedicineResultProps> = ({ 
    data, 
    profile, 
    isPremium, 
    isPreviouslyScanned, 
    overdoseWarning,
    onOpenPremium, 
    onClose 
}) => {
  const [speaking, setSpeaking] = useState(false);
  const [showCriticalModal, setShowCriticalModal] = useState(false);
  const [useEli5, setUseEli5] = useState(false);
  const [expandedDesc, setExpandedDesc] = useState(false);

  // Safety Defaults
  const questions = data?.commonQuestions || [];
  const timeline = data?.effectTimeline || { onset: 'N/A', peak: 'N/A', duration: 'N/A' };
  const lifestyle = data?.lifestyleWarnings || { alcohol: false, driving: false, sleep: false };
  const interaction = data?.interactionAnalysis;
  const medsList = data?.medicationsFound || [];

  useEffect(() => {
    if (data?.riskScore === 'High' || data?.criticalWarning || overdoseWarning || interaction?.severity === 'Dangerous') {
        setShowCriticalModal(true);
    }
    return () => { window.speechSynthesis.cancel(); }
  }, [data, overdoseWarning, interaction]);

  const speakText = (text: string) => {
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = profile?.language === 'hindi' ? 'hi-IN' : 'en-US';
    utterance.onend = () => setSpeaking(false);
    window.speechSynthesis.speak(utterance);
    setSpeaking(true);
  };

  const toggleSpeech = () => {
    if (speaking) {
        window.speechSynthesis.cancel();
        setSpeaking(false);
    } else {
        const textToRead = `${data?.name}. ${useEli5 ? data?.childFriendlyExplanation : data?.simpleExplanation}. ${data?.keyWarning || ''} ${interaction ? 'Interaction Check: ' + interaction.summary : ''}`;
        speakText(textToRead);
    }
  };

  const readWarningAloud = () => {
    const textToRead = overdoseWarning 
        ? "Attention! Potential Overdose detected. A recent scan of this medicine was found. Double-dosing can be very dangerous."
        : `Warning. ${data?.criticalWarning || 'High Risk Alert'}. ${interaction ? interaction.summary : ''} ${data?.riskReason || ''}`;
    speakText(textToRead);
  };

  const handleDownloadReport = () => {
      if (!isPremium) {
          onOpenPremium();
          return;
      }
      window.print();
  };

  const getHeaderColor = () => {
      if (overdoseWarning || data?.riskScore === 'High' || interaction?.severity === 'Dangerous') return 'bg-rose-600';
      if (data?.riskScore === 'Medium' || interaction?.severity === 'Warning') return 'bg-amber-500';
      return 'bg-teal-600';
