                                {interaction.severity}
                            </div>
                        </div>
                        <p className="text-slate-900 font-bold mb-3">{interaction.summary}</p>
                        <div className="text-xs text-slate-600 bg-white/50 p-4 rounded-2xl italic leading-relaxed">
                            {interaction.advice}
                        </div>
                    </div>
                </section>
