import React, { useState, useEffect } from 'react';
import { MedicineData, PatientProfile, Reminder } from '../types';
import { checkConditionSafety } from '../services/geminiService';

interface MedicineResultProps {
  data: MedicineData;
  profile?: PatientProfile;
  isPremium: boolean;
  isPreviouslyScanned: boolean;
  overdoseWarning?: boolean;
  onOpenPremium: () => void;
  onClose: () => void;
  onAddReminder?: (rem: Reminder) => void;
}

const MedicineResult: React.FC<MedicineResultProps> = ({ 
    data, 
    profile, 
    isPremium, 
    isPreviouslyScanned, 
    overdoseWarning,
    onOpenPremium, 
    onClose,
    onAddReminder
}) => {
  const [speaking, setSpeaking] = useState(false);
  const [showCriticalModal, setShowCriticalModal] = useState(false);
  const [useEli5, setUseEli5] = useState(false);
  const [expandedDesc, setExpandedDesc] = useState(false);

  // Safety Defaults
  const questions = data?.commonQuestions || [];
  const timeline = data?.effectTimeline || { onset: 'N/A', peak: 'N/A', duration: 'N/A' };
  const lifestyle = data?.lifestyleWarnings || { alcohol: false, driving: false, sleep: false };
  const interaction = data?.interactionAnalysis;
  const medsList = data?.medicationsFound || [];

  useEffect(() => {
    if (data?.riskScore === 'High' || data?.criticalWarning || overdoseWarning || interaction?.severity === 'Dangerous') {
        setShowCriticalModal(true);
    }
    return () => { window.speechSynthesis.cancel(); }
  }, [data, overdoseWarning, interaction]);

  const speakText = (text: string) => {
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = profile?.language === 'hindi' ? 'hi-IN' : 'en-US';
    utterance.onend = () => setSpeaking(false);
    window.speechSynthesis.speak(utterance);
    setSpeaking(true);
  };

  const toggleSpeech = () => {
    if (speaking) {
        window.speechSynthesis.cancel();
        setSpeaking(false);
    } else {
        const textToRead = `${data?.name}. ${useEli5 ? data?.childFriendlyExplanation : data?.simpleExplanation}. ${data?.keyWarning || ''} ${interaction ? 'Interaction Check: ' + interaction.summary : ''}`;
        speakText(textToRead);
    }
  };

  const handleQuickReminder = () => {
    if (onAddReminder) {
      const now = new Date();
      now.setMinutes(0);
      now.setHours(now.getHours() + 1); // Default to next hour
      const timeStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;

      onAddReminder({
        id: Date.now().toString(),
        medicineName: data.name,
        dose: data.dosage || '1 unit',
        time: timeStr,
        foodContext: data.foodGuidance.toLowerCase().includes('before') ? 'before_food' : 'after_food',
        repeat: 'daily',
        customDays: [],
        soundType: 'voice',
        voiceTone: 'friendly',
        voiceGender: 'female',
        active: true,
        snoozedUntil: null,
        createdAt: Date.now()
      });
    }
  };

  const handleDownloadReport = () => {
      if (!isPremium) {
          onOpenPremium();
          return;
      }
      window.print();
  };

  const getHeaderColor = () => {
      if (overdoseWarning || data?.riskScore === 'High' || interaction?.severity === 'Dangerous') return 'bg-rose-600';
      if (data?.riskScore === 'Medium' || interaction?.severity === 'Warning') return 'bg-amber-500';
      return 'bg-teal-600';
  };

  if (!data) return null;

  const PremiumLock = ({ title }: { title: string }) => (
    <div className="absolute inset-0 bg-white/40 backdrop-blur-[3px] flex flex-col items-center justify-center p-6 text-center z-10 rounded-[2rem]">
        <div className="w-12 h-12 bg-white rounded-2xl shadow-xl flex items-center justify-center mb-4 border border-slate-100">
            <span className="text-xl">👑</span>
        </div>
        <h4 className="text-slate-900 font-black text-[11px] uppercase tracking-tighter mb-1">{title} is Premium</h4>
        <button 
            onClick={onOpenPremium}
            className="bg-slate-900 text-white px-5 py-2.5 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-xl active:scale-95 transition-all"
        >
            Unlock Forever ₹99
        </button>
    </div>
  );

  return (
    <div className="bg-slate-50 min-h-screen pb-32 animate-fade-in relative z-50 print:bg-white print:p-0 print:m-0">

        {/* Style for print */}
        <style dangerouslySetInnerHTML={{ __html: `
            @media print {
                nav, footer, button, .PremiumLock, header button, .print-hide { display: none !important; }
                .print-only { display: block !important; }
                body { background: white !important; }
                .bg-slate-50 { background: white !important; }
                .rounded-[2rem], .rounded-[3rem], .rounded-b-[3rem] { border-radius: 0 !important; }
                .shadow-2xl, .shadow-sm { box-shadow: none !important; border: 1px solid #eee !important; }
                header { background: #0d9488 !important; color: white !important; padding: 40px !important; margin-bottom: 20px !important; }
            }
        `}} />

        <div className="hidden print:block print-only text-center py-6 border-b-2 border-slate-900 mb-8">
            <h1 className="text-4xl font-black text-slate-900 uppercase tracking-tighter">Medical Safety Report</h1>
            <p className="text-slate-400 font-bold uppercase tracking-widest text-[10px] mt-2">Generated by MedScan AI Assistance</p>
        </div>

        <header className={`${getHeaderColor()} text-white rounded-b-[3rem] shadow-2xl relative overflow-hidden pb-12 print:rounded-none`}>
