import React, { useState, useEffect } from 'react';
import { MedicineData, PatientProfile, Reminder } from '../types';

interface MedicineResultProps {
  data: MedicineData;
  profile?: PatientProfile;
  isPremium: boolean;
  isPreviouslyScanned: boolean;
  overdoseWarning?: boolean;
  onOpenPremium: () => void;
  onClose: () => void;
  onAddReminder?: (rem: Reminder) => void;
}

const MedicineResult: React.FC<MedicineResultProps> = ({ 
    data, 
    profile, 
    isPremium, 
    isPreviouslyScanned, 
    overdoseWarning,
    onOpenPremium, 
    onClose,
    onAddReminder
}) => {
  const [speaking, setSpeaking] = useState(false);
  const [useEli5, setUseEli5] = useState(false);

  const timeline = data?.effectTimeline || { onset: 'N/A', peak: 'N/A', duration: 'N/A' };
  const lifestyle = data?.lifestyleWarnings || { alcohol: false, driving: false, sleep: false };
  const interaction = data?.interactionAnalysis;
  const medsList = data?.medicationsFound || [];

  const handleDownloadReport = () => {
      if (!isPremium) {
          onOpenPremium();
          return;
      }
      window.print();
  };

  const handleQuickReminder = () => {
    if (onAddReminder) {
      const now = new Date();
      now.setMinutes(0);
      now.setHours(now.getHours() + 1); 
      const timeStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;

      onAddReminder({
        id: Date.now().toString(),
        medicineName: data.name,
        dose: data.dosage || '1 unit',
        time: timeStr,
        foodContext: data.foodGuidance.toLowerCase().includes('before') ? 'before_food' : 'after_food',
        repeat: 'daily',
        customDays: [],
        soundType: 'voice',
        voiceTone: 'friendly',
        voiceGender: 'female',
        active: true,
        snoozedUntil: null,
        createdAt: Date.now()
      });
    }
  };

  const getHeaderColor = () => {
      if (overdoseWarning || data?.riskScore === 'High' || interaction?.severity === 'Dangerous') return 'bg-rose-600';
      if (data?.riskScore === 'Medium' || interaction?.severity === 'Warning') return 'bg-amber-500';
      return 'bg-teal-600';
  };

  if (!data) return null;

  return (
    <div className="bg-slate-50 min-h-screen pb-32 animate-fade-in relative z-50 print:bg-white print:p-0 print:m-0">
        <style dangerouslySetInnerHTML={{ __html: `
            @media print {
                nav, footer, button, .PremiumLock, header button, .print-hide { display: none !important; }
                .print-only { display: block !important; }
                body { background: white !important; }
                .bg-slate-50 { background: white !important; }
                .rounded-[2rem], .rounded-[3rem], .rounded-b-[3rem] { border-radius: 0 !important; }
                .shadow-2xl, .shadow-sm { box-shadow: none !important; border: 1px solid #eee !important; }
                header { background: #0d9488 !important; color: white !important; padding: 40px !important; margin-bottom: 20px !important; }
            }
        `}} />

        <div className="hidden print:block print-only text-center py-6 border-b-2 border-slate-900 mb-8">
            <h1 className="text-4xl font-black text-slate-900 uppercase tracking-tighter">Medical Safety Report</h1>
            <p className="text-slate-400 font-bold uppercase tracking-widest text-[10px] mt-2">Generated by MedScan AI Assistance</p>
        </div>

        <header className={`${getHeaderColor()} text-white rounded-b-[3rem] shadow-2xl relative overflow-hidden pb-12 print:rounded-none`}>
            <div className="p-6 pt-8 relative z-10">
                <div className="flex justify-between items-start mb-6">
                    <div className="bg-black/20 backdrop-blur-md px-3 py-1.5 rounded-lg border border-white/10">
                        <span className="text-[10px] font-bold tracking-widest uppercase">Risk: {data?.riskScore}</span>
                    </div>
                    <button onClick={onClose} className="bg-white/10 p-2.5 rounded-full border border-white/10 print-hide">
                        <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                </div>
                <h2 className="text-3xl font-extrabold mb-2 tracking-tight">{data.name}</h2>
                <div className="flex flex-wrap gap-2 mb-4">
                    {medsList.map((m, i) => (
                        <span key={i} className="text-[9px] font-black uppercase bg-white/10 px-2 py-1 rounded-md">{m}</span>
                    ))}
                </div>
                <div className="text-white/90 text-sm font-medium leading-relaxed">{data.description}</div>
            </div>
        </header>

        <div className="px-5 pt-12 space-y-6">
            <section className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest">AI Summary</h3>
                    <button onClick={() => setUseEli5(!useEli5)} className="text-[10px] font-bold px-3 py-1.5 rounded-full bg-slate-50 text-slate-500 border border-slate-200 print-hide">
                        {useEli5 ? 'Deep' : 'Simple'}
                    </button>
                </div>
                <p className="text-slate-800 text-lg font-medium leading-relaxed">
                    "{useEli5 ? data?.childFriendlyExplanation : data?.simpleExplanation}"
                </p>
            </section>

             <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100">
                <h3 className="text-xs font-bold text-slate-400 uppercase mb-8 tracking-widest">Effect Timeline</h3>
                <div className="flex justify-between items-start px-2">
                    {[
                        { label: "Starts", val: timeline.onset, emoji: "⏱️" },
                        { label: "Peak", val: timeline.peak, emoji: "📈" },
                        { label: "Lasts", val: timeline.duration, emoji: "⌛" }
                    ].map((item, i) => (
                        <div key={i} className="flex flex-col items-center">
                            <div className="w-9 h-9 bg-teal-50 rounded-2xl flex items-center justify-center mb-3">
                                 <span className="text-[14px]">{item.emoji}</span>
                            </div>
                            <p className="text-[10px] text-slate-400 font-black uppercase mb-1">{item.label}</p>
                            <p className="text-xs font-black text-slate-900">{item.val}</p>
                        </div>
                    ))}
                </div>
             </div>

             <section className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100">
                <h3 className="text-xs font-bold text-slate-400 uppercase mb-4 tracking-widest">Risks & Avoidance</h3>
                <div className="space-y-4">
                    <div className="bg-rose-50/50 p-4 rounded-2xl border border-rose-100/50">
                        <span className="text-[9px] font-black text-rose-500 uppercase block mb-1">Key Warning</span>
                        <p className="text-xs font-bold text-slate-700 leading-relaxed">{data.warnings}</p>
                    </div>
                </div>
             </section>

            <div className="space-y-3 pt-2 print-hide">
                <button onClick={handleQuickReminder} className="w-full bg-teal-500 text-white py-5 rounded-2xl font-black text-xs uppercase tracking-widest shadow-lg flex items-center justify-center">
                    Set Daily Alarm 🔔
                </button>
                <button onClick={handleDownloadReport} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-xs uppercase tracking-widest shadow-lg flex items-center justify-center">
                    {isPremium ? 'Download Professional Report PDF' : 'Unlock Professional Report 👑'}
                </button>
                <button onClick={onClose} className="w-full bg-white text-teal-700 py-4 rounded-2xl font-black text-xs uppercase tracking-widest border border-slate-100 shadow-sm">
                    Back to Scanner
                </button>
            </div>

            <div className="hidden print:block text-center pt-10 border-t border-slate-100 text-[9px] text-slate-400 uppercase font-bold">
              Disclaimer: This report is generated by MedScan AI. Always verify medical decisions with a qualified healthcare professional.
            </div>
        </div>
    </div>
  );
};

export default MedicineResult;

import React, { useState } from 'react';
import { FamilyMember, AgeGroup, Gender, Language } from '../types';

interface ProfileProps {
  isPremium: boolean;
  familyMembers: FamilyMember[];
  setFamilyMembers: (members: FamilyMember[]) => void;
}

const Profile: React.FC<ProfileProps> = ({ isPremium, familyMembers, setFamilyMembers }) => {
  const [showAddModal, setShowAddModal] = useState(false);
  const [newName, setNewName] = useState('');
  const [newAge, setNewAge] = useState<AgeGroup>('adult');
  const [newGender, setNewGender] = useState<Gender>('male');
  const [newLang, setNewLang] = useState<Language>('english');

  const addMember = () => {
    if (!newName) return;
    const avatars = ['🧑', '👧', '👶', '👵', '👴', '👲'];
    const newMember: FamilyMember = {
      id: crypto.randomUUID(),
      name: newName,
      ageGroup: newAge,
      gender: newGender,
      isPregnant: false,
      isBreastfeeding: false,
      language: newLang,
      avatar: avatars[Math.floor(Math.random() * avatars.length)]
    };
    setFamilyMembers([...familyMembers, newMember]);
    setShowAddModal(false);
    setNewName('');
  };

  const removeMember = (id: string) => {
    if (id === 'me') return;
    if (confirm("Remove this profile?")) {
      setFamilyMembers(familyMembers.filter(m => m.id !== id));
    }
  };

  return (
    <div className="p-6 pb-24 animate-fade-in-up">
        <h2 className="text-2xl font-bold text-gray-900 mb-6">Health Profile</h2>

        <div className="bg-white rounded-3xl p-6 shadow-xl border border-gray-100 mb-8 text-center relative overflow-hidden">
            <div className={`absolute top-0 left-0 w-full h-28 bg-gradient-to-r ${isPremium ? 'from-yellow-400 to-orange-500' : 'from-teal-500 to-emerald-600'}`}></div>
            <div className="relative z-10 -mt-2">
                <div className="w-24 h-24 rounded-full border-4 border-white shadow-lg mx-auto bg-gray-200 flex items-center justify-center text-3xl">
                    👤 {isPremium && <span className="absolute -bottom-2 -right-2 text-2xl">👑</span>}
                </div>
                <h3 className="text-xl font-bold mt-3 text-gray-800">Guest User</h3>
                <div className="inline-flex items-center px-4 py-1.5 rounded-full bg-gray-100 text-gray-500 font-bold text-sm mt-4">
                     <span>{isPremium ? 'Premium Plan' : 'Free Plan'}</span>
                </div>
            </div>
        </div>

        <div className="mb-8">
            <div className="flex justify-between items-center mb-4">
              <h4 className="text-sm font-black text-slate-900 uppercase tracking-wider">Family Profiles</h4>
              <button onClick={() => setShowAddModal(true)} className="text-[10px] font-black text-teal-600 uppercase tracking-widest bg-teal-50 px-3 py-1.5 rounded-lg border border-teal-100">+ Add</button>
            </div>
            <div className="grid grid-cols-2 gap-4">
              {familyMembers.map(member => (
                <div key={member.id} className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm relative group">
                  <div className="text-3xl mb-2">{member.avatar}</div>
                  <h5 className="font-bold text-slate-800 text-sm truncate">{member.name}</h5>
                  <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest mt-1">{member.ageGroup} • {member.gender}</p>
                  {member.id !== 'me' && (
                    <button onClick={() => removeMember(member.id)} className="absolute top-2 right-2 p-1 text-slate-200 hover:text-rose-500 opacity-0 group-hover:opacity-100">
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                  )}
                </div>
              ))}
            </div>
        </div>

        {showAddModal && (
          <div className="fixed inset-0 z-[200] bg-slate-900/80 backdrop-blur-sm flex items-end sm:items-center justify-center p-0 sm:p-4">
            <div className="bg-white rounded-t-[2.5rem] sm:rounded-[2.5rem] w-full max-w-sm p-8 shadow-2xl animate-slide-up">
              <h3 className="text-xl font-black text-slate-900 mb-6">New Profile</h3>
              <div className="space-y-6">
                <input type="text" value={newName} onChange={(e) => setNewName(e.target.value)} placeholder="e.g. Grandma" className="w-full bg-slate-50 p-4 rounded-xl border border-slate-100 font-bold" />
                <div className="grid grid-cols-2 gap-4">
                  <select value={newAge} onChange={(e) => setNewAge(e.target.value as AgeGroup)} className="bg-slate-50 p-4 rounded-xl font-bold">
                    <option value="child">Child</option><option value="adult">Adult</option><option value="senior">Senior</option>
                  </select>
                  <select value={newGender} onChange={(e) => setNewGender(e.target.value as Gender)} className="bg-slate-50 p-4 rounded-xl font-bold">
                    <option value="male">Male</option><option value="female">Female</option>
                  </select>
                </div>
                <div className="flex space-x-3 pt-4">
                  <button onClick={() => setShowAddModal(false)} className="flex-1 bg-slate-100 text-slate-500 py-4 rounded-2xl font-black text-xs uppercase">Cancel</button>
                  <button onClick={addMember} className="flex-[2] bg-teal-600 text-white py-4 rounded-2xl font-black text-xs uppercase shadow-lg shadow-teal-600/20">Save</button>
                </div>
              </div>
            </div>
          </div>
        )}
    </div>
  );
};

