import React, { useState } from 'react';
import { FamilyMember, AgeGroup, Gender, Language, User } from '../types';

interface ProfileProps {
  isPremium: boolean;
  familyMembers: FamilyMember[];
  setFamilyMembers: (members: FamilyMember[]) => void;
  user: User | null;
  onLogin: () => void;
  onLogout: () => void;
}

