import React, { useState, useEffect, useCallback } from 'react';
import Scanner from './components/Scanner.tsx';
import MedicineResult from './components/MedicineResult.tsx';
import Reminders from './components/Reminders.tsx';
import History from './components/History.tsx';
import DoctorAI from './components/DoctorAI.tsx';
import PremiumModal from './components/PremiumModal.tsx';
import Profile from './components/Profile.tsx';
import LegalAndHelp from './components/LegalAndHelp.tsx';
import AlarmRingingModal from './components/AlarmRingingModal.tsx';
import IntroFlow from './components/IntroFlow.tsx';
import LoginScreen from './components/LoginScreen.tsx';
import { MedicineData, AppView, Reminder, PatientProfile, ScanHistoryItem, FamilyMember, User } from './types.ts';
import { getHealthTip } from './services/geminiService.ts';
import { subscribeToAuthChanges, loginWithGoogle, logout, handleRedirectResult } from './services/authService.ts';

const App: React.FC = () => {
  // -- Auth State --
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isGuest, setIsGuest] = useState<boolean>(() => localStorage.getItem('mediScan_is_guest') === 'true');
  const [authChecked, setAuthChecked] = useState(false);
  const [showIntro, setShowIntro] = useState<boolean>(true);

  // -- Data State (Initialized Empty, Loaded via Effect) --
  const [reminders, setReminders] = useState<Reminder[]>([]);
  const [scanHistory, setScanHistory] = useState<ScanHistoryItem[]>([]);
  const [familyMembers, setFamilyMembers] = useState<FamilyMember[]>([]);
  const [isPremium, setIsPremium] = useState<boolean>(false);

  // -- UI State --
  const [currentView, setCurrentView] = useState<AppView>(AppView.HOME);
  const [scannedData, setScannedData] = useState<MedicineData | null>(null);
  const [patientProfile, setPatientProfile] = useState<PatientProfile | undefined>(undefined);
  const [showPremiumModal, setShowPremiumModal] = useState(false);
  const [healthTip, setHealthTip] = useState<string>("");
  const [isPreviouslyScanned, setIsPreviouslyScanned] = useState(false);
  const [overdoseWarning, setOverdoseWarning] = useState(false);
  const [activeAlarm, setActiveAlarm] = useState<Reminder | null>(null);
  const [notificationPermission, setNotificationPermission] = useState<NotificationPermission>(() => Notification.permission);
  const [isLoadingData, setIsLoadingData] = useState(true);

  // Helper: Generate Storage Key based on User
  // Guests use legacy keys (no prefix) to preserve existing data.
  // Logged-in users use `mediScan_UID_` prefix.
  const getStorageKey = useCallback((baseKey: string) => {
    if (currentUser) {
      return `mediScan_${currentUser.uid}_${baseKey}`;
    }
    return `mediScan_${baseKey}`;
  }, [currentUser]);

  // -- Initialization & Auth --
  useEffect(() => {
    // 1. Check Intro
    const introSeen = localStorage.getItem('mediScan_intro_seen');
    if (introSeen) setShowIntro(false);

    // 2. Handle Redirect Result (Important for Mobile Login)
    handleRedirectResult().catch((error) => {
        console.error("Redirect Error:", error);
        // Errors are usually handled by the auth state listener, but specific redirect errors can be logged here
    });

    // 3. Auth Subscription
    const unsubscribe = subscribeToAuthChanges((user) => {
      setCurrentUser(user);
      setAuthChecked(true);
      if (user) {
          setIsGuest(false);
          localStorage.removeItem('mediScan_is_guest');
      }
    });

    // 4. Health Tip & Device ID
    if (!localStorage.getItem('mediScan_deviceId')) {
        localStorage.setItem('mediScan_deviceId', crypto.randomUUID());
    }
    getHealthTip().then(setHealthTip).catch(() => setHealthTip("Always verify medicine with a doctor."));

    return () => unsubscribe();
  }, []);

  // -- Load Data when User Changes --
  useEffect(() => {
    if (!authChecked) return;
    if (!currentUser && !isGuest) return; // Wait for login choice

    setIsLoadingData(true);

    // Load Reminders
    try {
        const saved = localStorage.getItem(getStorageKey('reminders'));
        setReminders(saved ? JSON.parse(saved) : []);
    } catch { setReminders([]); }

    // Load History
    try {
        const saved = localStorage.getItem(getStorageKey('history'));
        setScanHistory(saved ? JSON.parse(saved) : []);
    } catch { setScanHistory([]); }

    // Load Family
    try {
        const saved = localStorage.getItem(getStorageKey('family'));
        if (saved) {
            setFamilyMembers(JSON.parse(saved));
        } else {
            // Default Profile
            const defaultMe: FamilyMember = {
                id: 'me',
                name: currentUser?.displayName || 'Me',
                ageGroup: 'adult',
                gender: 'male',
                isPregnant: false,
                isBreastfeeding: false,
                language: 'english',
                avatar: currentUser?.photoURL ? '📸' : '🧑‍💻'
            };
            setFamilyMembers([defaultMe]);
        }
    } catch { setFamilyMembers([]); }

    // Load Premium
    try {
        const saved = localStorage.getItem(getStorageKey('premium'));
        setIsPremium(saved === 'true');
    } catch { setIsPremium(false); }

    setIsLoadingData(false);

  }, [currentUser, isGuest, authChecked, getStorageKey]);

  // -- Save Data Effects (Triggered on State Change) --
  useEffect(() => {
    if (isLoadingData) return;
    localStorage.setItem(getStorageKey('reminders'), JSON.stringify(reminders));
  }, [reminders, getStorageKey, isLoadingData]);

  useEffect(() => {
    if (isLoadingData) return;
    localStorage.setItem(getStorageKey('history'), JSON.stringify(scanHistory));
  }, [scanHistory, getStorageKey, isLoadingData]);

  useEffect(() => {
    if (isLoadingData) return;
    localStorage.setItem(getStorageKey('family'), JSON.stringify(familyMembers));
  }, [familyMembers, getStorageKey, isLoadingData]);

  useEffect(() => {
    if (isLoadingData) return;
    localStorage.setItem(getStorageKey('premium'), String(isPremium));
  }, [isPremium, getStorageKey, isLoadingData]);


  // -- Alarm Checker --
  useEffect(() => {
    const interval = setInterval(() => {
        const now = new Date();
        const currentTime = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;

        const triggered = reminders.find(r => r.active && r.time === currentTime && (!r.snoozedUntil || Date.now() >= r.snoozedUntil));
        if (triggered && !activeAlarm) {
            setActiveAlarm(triggered);
        }
    }, 10000); 

    return () => clearInterval(interval);
  }, [reminders, activeAlarm]);

  // -- Handlers --

  const requestNotificationPermission = async () => {
    if (Notification.permission === 'default') {
      const permission = await Notification.requestPermission();
      setNotificationPermission(permission);
    }
  };

  const handleUpgrade = async (txnId?: string) => {
    setIsPremium(true);
    if (txnId) localStorage.setItem(getStorageKey('txnId'), txnId);
    setShowPremiumModal(false);
    setCurrentView(AppView.PROFILE);
  };

  const handleLogin = async () => {
    try {
        await loginWithGoogle();
        // State reset handled by auth subscription + data loading effect
    } catch (error) {
        // With redirect, this catch might not trigger for webview issues, but handleRedirectResult will log it
        alert("Login initiation failed. Please try again.");
    }
  };

  const handleGuestContinue = () => {
      setIsGuest(true);
      localStorage.setItem('mediScan_is_guest', 'true');
  };

  const handleLogout = async () => {
    try {
        await logout();
        setIsGuest(false);
        setScannedData(null);
        setCurrentView(AppView.HOME);
        localStorage.removeItem('mediScan_is_guest');
    } catch (error) {
        console.error("Logout failed", error);
    }
  };

  const addReminder = (r: Reminder) => setReminders(prev => [...prev, r]);
  const deleteReminder = (id: string) => setReminders(prev => prev.filter(r => r.id !== id));
  const toggleReminder = (id: string) => setReminders(prev => prev.map(r => r.id === id ? { ...r, active: !r.active } : r));
  const updateReminder = (updated: Reminder) => setReminders(prev => prev.map(r => r.id === updated.id ? updated : r));

  const handleScanComplete = (data: MedicineData, profile: PatientProfile) => {
    const now = Date.now();
    const fourHours = 4 * 60 * 60 * 1000;
    const recentScan = scanHistory.find(item => {
        const isSameMed = item.medicineName.toLowerCase().trim() === data.name.toLowerCase().trim();
        const isRecent = (now - item.timestamp) < fourHours;
        return isSameMed && isRecent;
    });
    setIsPreviouslyScanned(scanHistory.some(item => item.medicineName.toLowerCase().trim() === data.name.toLowerCase().trim()));
    setOverdoseWarning(!!recentScan);
    setScanHistory(prev => [{ id: crypto.randomUUID(), timestamp: now, medicineName: data.name, data }, ...prev].slice(0, 20));
    setScannedData(data);
    setPatientProfile(profile);
  };

  const handleIntroComplete = () => {
    localStorage.setItem('mediScan_intro_seen', 'true');
    setShowIntro(false);
  };

  // -- Render Flow --

  if (showIntro) {
    return <IntroFlow onComplete={handleIntroComplete} />;
  }

  // Show Login Screen if:
  // 1. Auth check is done
  // 2. No user logged in
  // 3. Not in guest mode
  if (authChecked && !currentUser && !isGuest) {
      return <LoginScreen onLogin={handleLogin} onGuest={handleGuestContinue} />;
  }

  const renderContent = () => {
    if (scannedData) {
      return (
        <MedicineResult 
          data={scannedData} 
          profile={patientProfile} 
          isPremium={isPremium} 
          isPreviouslyScanned={isPreviouslyScanned} 
          overdoseWarning={overdoseWarning} 
          onOpenPremium={() => setShowPremiumModal(true)} 
          onClose={() => setScannedData(null)}
          onAddReminder={(rem) => {
            addReminder(rem);
            setCurrentView(AppView.REMINDERS);
            setScannedData(null);
          }}
        />
      );
    }

    switch (currentView) {
      case AppView.HOME:
      case AppView.SCANNER:
        return (
          <div className="bg-slate-50 min-h-screen">
            <header className="sticky top-0 z-50 bg-slate-50 px-6 pt-10 pb-4 flex justify-between items-center shadow-sm border-b border-slate-100/50">
               <div className="group cursor-default">
                   <div className="flex items-center space-x-2.5">
                       <h1 className="text-4xl font-extrabold tracking-tighter bg-gradient-to-br from-slate-900 via-teal-800 to-slate-800 bg-clip-text text-transparent">MediIQ</h1>
                       <div className="w-2.5 h-2.5 bg-rose-500 rounded-full animate-heartbeat shadow-[0_0_12px_rgba(244,63,94,0.6)]"></div>
                   </div>
                   <p className="text-[10px] font-bold uppercase tracking-[0.3em] text-slate-400 ml-0.5 mt-1.5 opacity-60">AI Health Companion</p>
               </div>
               <button onClick={() => setCurrentView(AppView.INFO)} className="w-11 h-11 bg-white flex items-center justify-center rounded-2xl shadow-xl shadow-slate-200/50 border border-slate-50 text-slate-400 hover:text-teal-600 transition-all active:scale-90">
                   <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
               </button>
            </header>

            <div className="px-6 pb-32 pt-6 max-w-lg mx-auto">
                {healthTip && (
                     <div className="mb-10 p-6 bg-white border border-teal-50/50 rounded-[2.5rem] flex items-start shadow-xl shadow-teal-900/5 animate-slide-up hover:shadow-teal-900/10 transition-shadow">
                        <div className="w-12 h-12 bg-teal-50 rounded-2xl flex items-center justify-center mr-4 shrink-0 text-2xl shadow-inner">💊</div>
                        <div>
                            <h4 className="text-[10px] font-black text-teal-600/70 uppercase tracking-widest mb-1.5">Smart Tip</h4>
                            <span className="text-sm text-slate-700 font-bold leading-relaxed">{healthTip}</span>
                        </div>
                     </div>
                )}

                <Scanner familyMembers={familyMembers} onScanComplete={handleScanComplete} onError={(msg) => alert(msg)} />

                {!isPremium && (
                    <div onClick={() => setShowPremiumModal(true)} className="mt-10 bg-slate-900 text-white p-7 rounded-[3rem] shadow-2xl shadow-slate-900/20 flex justify-between items-center cursor-pointer transform transition-all hover:translate-y-[-2px] active:scale-95 group relative overflow-hidden border border-slate-800">
                        <div className="absolute inset-0 bg-gradient-to-br from-slate-800 to-slate-900 z-0"></div>
                        <div className="absolute -top-12 -right-12 w-48 h-48 bg-white opacity-[0.05] rounded-full blur-3xl group-hover:opacity-10 transition-opacity"></div>
                        <div className="relative z-10 text-left">
                            <h3 className="font-extrabold text-xl flex items-center tracking-tight">Expert Insights <span className="ml-2">💎</span></h3>
                            <p className="text-[10px] text-slate-500 mt-1 font-black uppercase tracking-widest opacity-80">Unlock Detailed Safety Reports</p>
                        </div>
                        <div className="relative z-10 bg-white text-slate-900 px-6 py-3 rounded-2xl font-black text-xs shadow-xl tracking-widest uppercase">₹99</div>
                    </div>
                )}
            </div>
          </div>
        );
      case AppView.REMINDERS:
        return <div className="pb-24 bg-slate-50 min-h-screen"><Reminders reminders={reminders} addReminder={addReminder} updateReminder={updateReminder} deleteReminder={deleteReminder} toggleReminder={toggleReminder} notificationPermission={notificationPermission} onRequestNotificationPermission={requestNotificationPermission} /></div>;
      case AppView.HISTORY:
        return <div className="pb-24 bg-slate-50 min-h-screen"><History history={scanHistory} onSelectItem={(data) => { setScannedData(data); setOverdoseWarning(false); setIsPreviouslyScanned(true); }} onClearHistory={() => setScanHistory([])} /></div>;
      case AppView.DOCTOR_AI:
        return <DoctorAI isPremium={isPremium} onOpenPremium={() => setShowPremiumModal(true)} userId={currentUser?.uid || 'guest'} />;
      case AppView.INFO:
          return <div className="pb-24 bg-slate-50 min-h-screen"><LegalAndHelp /></div>;
      case AppView.PROFILE:
          return (
            <div className="pb-24 bg-slate-50 min-h-screen">
              <Profile 
                isPremium={isPremium} 
                familyMembers={familyMembers} 
                setFamilyMembers={setFamilyMembers} 
                user={currentUser}
                onLogin={handleLogin}
                onLogout={handleLogout}
              />
            </div>
          );
      default:
        return <div className="p-10 text-center">View not found</div>;
    }
  };

  return (
    <div className="max-w-md mx-auto min-h-screen relative shadow-2xl overflow-hidden font-sans text-slate-800 bg-slate-50">
      <main className="min-h-screen relative z-10 overflow-y-auto hide-scrollbar bg-slate-50">
        {renderContent()}
      </main>

      {activeAlarm && (
          <AlarmRingingModal 
            reminder={activeAlarm} 
            onTake={() => { setActiveAlarm(null); toggleReminder(activeAlarm.id); }}
            onSnooze={(mins) => { setActiveAlarm(null); }}
            onSkip={() => { setActiveAlarm(null); }}
            notificationPermission={notificationPermission}
          />
      )}

      {!scannedData && !activeAlarm && (
        <div className="fixed bottom-0 left-0 right-0 max-w-md mx-auto z-[100] bg-white border-t border-slate-100 shadow-[0_-5px_20px_rgba(0,0,0,0.05)] pb-safe">
            <nav className="flex justify-around items-center px-2 py-3">
                {[
                    { view: AppView.HOME, icon: "M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z M15 13a3 3 0 11-6 0 3 3 0 016 0z", label: "Scan" },
                    { view: AppView.REMINDERS, icon: "M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z", label: "Alarms" },
                    { view: AppView.DOCTOR_AI, icon: "M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z", label: "Doctor" },
                    { view: AppView.HISTORY, icon: "M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z", label: "History" },
                    { view: AppView.PROFILE, icon: "M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z", label: "Me" }
                ].map((item) => {
                    const isActive = currentView === item.view || (item.view === AppView.HOME && currentView === AppView.SCANNER);
                    return (
                        <button key={item.label} onClick={() => setCurrentView(item.view)} className={`flex flex-col items-center justify-center w-16 py-1 rounded-xl transition-all duration-300 ${isActive ? 'text-slate-900' : 'text-slate-400 hover:text-slate-600'}`}>
                            <div className={`mb-1 transition-all duration-300 ${isActive ? 'bg-slate-900 text-white p-2.5 rounded-2xl shadow-lg' : ''}`}>
                                <svg className={`w-6 h-6 ${isActive ? 'stroke-2' : 'stroke-[1.5]'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" d={
                                    item.view === AppView.DOCTOR_AI ? "M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" : 
                                    item.view === AppView.HISTORY ? "M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" : 
                                    item.icon
                                } />
                                </svg>
                            </div>
                            <span className={`text-[10px] font-bold tracking-tight ${isActive ? 'font-black' : 'font-medium'}`}>{item.label}</span>
                        </button>
                    );
                })}
            </nav>
        </div>
      )}
      <PremiumModal isOpen={showPremiumModal} onClose={() => setShowPremiumModal(false)} onUpgrade={handleUpgrade} />
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { Reminder } from '../types';

interface AlarmRingingModalProps {
  reminder: Reminder;
  onTake: () => void;
  onSnooze: (minutes: number) => void;
  onSkip: () => void;
  notificationPermission: NotificationPermission;
}

const AlarmRingingModal: React.FC<AlarmRingingModalProps> = ({ reminder, onTake, onSnooze, onSkip, notificationPermission }) => {
  const [volumeLevel, setVolumeLevel] = useState(0.8); // Start higher for immediate audibility
  const audioContextRef = useRef<AudioContext | null>(null);
  const gainNodeRef = useRef<GainNode | null>(null); // Dedicated gain node for tone volume control
  const intervalRef = useRef<number | null>(null);
  const customAudioRef = useRef<HTMLAudioElement | null>(null);
  const notificationTagRef = useRef<string>(`mediIQ-alarm-${reminder.id}`); // Unique tag for notification

  // Vibrate on alarm
  useEffect(() => {
    if (navigator.vibrate) {
        const pattern = [500, 200, 500, 200, 500, 500, 1000];
        navigator.vibrate(pattern);
        const vibeInterval = setInterval(() => navigator.vibrate(pattern), 4000);
        return () => { clearInterval(vibeInterval); navigator.vibrate(0); };
    }
  }, []);

  // Handle Web Notification
  useEffect(() => {
    if (notificationPermission === 'granted') {
      const notificationTitle = `Medication Reminder: ${reminder.medicineName}`;
      const notificationOptions: NotificationOptions = {
        body: `${reminder.dose}, ${reminder.foodContext.replace('_', ' ')}.`,
        icon: '/favicon.png', // Or a more relevant icon
        tag: notificationTagRef.current, // Use a unique tag to replace/close later
      };

      try {
        // Check if there's already a notification with this tag and close it before creating a new one
        if (('getNotifications' in ServiceWorkerRegistration.prototype) && navigator.serviceWorker.ready) {
          navigator.serviceWorker.ready.then(registration => {
            registration.getNotifications({ tag: notificationTagRef.current }).then(notifications => {
              notifications.forEach(notification => notification.close());
              new Notification(notificationTitle, notificationOptions);
            });
          }).catch(e => console.error("ServiceWorker registration error for notification:", e));
        } else {
          new Notification(notificationTitle, notificationOptions);
        }
      } catch (error) {
        console.error("Failed to show web notification:", error);
      }
    }

    // Function to close the notification when modal is dismissed
    const closeNotification = () => {
        if (notificationPermission === 'granted' && 'getNotifications' in ServiceWorkerRegistration.prototype) {
             navigator.serviceWorker.ready.then(registration => {
                 registration.getNotifications({ tag: notificationTagRef.current }).then(notifications => {
                     notifications.forEach(notification => notification.close());
                 });
             }).catch(e => console.error("ServiceWorker registration error for closing notification:", e));
        }
    };

    // Clean up function to close the notification when component unmounts
    return () => closeNotification();
  }, [notificationPermission, reminder]);

  const getSpeechVoice = useCallback((gender: 'male' | 'female', lang: string = 'en-US'): SpeechSynthesisVoice | null => {
    const voices = window.speechSynthesis.getVoices();
    const langPrefix = lang.substring(0, 2).toLowerCase();

    // Filter voices primarily by language
    const filteredVoicesByLang = voices.filter(voice => voice.lang.toLowerCase().startsWith(langPrefix));

    let selectedVoice: SpeechSynthesisVoice | null = null;

    if (gender === 'male') {
        // Prioritize explicit male voice names or strong male indicators
        selectedVoice = filteredVoicesByLang.find(voice => 
            voice.name.toLowerCase().includes('male') || 
            voice.name.toLowerCase().includes('david') || 
            voice.name.toLowerCase().includes('aaron') ||
            voice.name.toLowerCase().includes('daniel') ||
            (voice.name.toLowerCase().includes('google') && voice.name.toLowerCase().includes('us english') && !voice.name.toLowerCase().includes('female')) ||
            (!voice.name.toLowerCase().includes('female') && !voice.name.toLowerCase().includes('zira') && !voice.name.toLowerCase().includes('sara') && !voice.name.toLowerCase().includes('helen')) // Aggressively exclude known female names
        );

        // Fallback 1: If no specific male voice in current language, try any male voice from all voices
        if (!selectedVoice) {
            selectedVoice = voices.find(voice =>
                (voice.name.toLowerCase().includes('male') ||
                voice.name.toLowerCase().includes('david') ||
                voice.name.toLowerCase().includes('aaron') ||
                voice.name.toLowerCase().includes('daniel')) &&
                !voice.name.toLowerCase().includes('female') && !voice.name.toLowerCase().includes('zira') && !voice.name.toLowerCase().includes('sara')
            );
        }

    } else { // female
        // Prioritize explicit female voice names or strong female indicators
        selectedVoice = filteredVoicesByLang.find(voice => 
            voice.name.toLowerCase().includes('female') || 
            voice.name.toLowerCase().includes('zira') || 
            voice.name.toLowerCase().includes('sara') ||
            voice.name.toLowerCase().includes('helen') ||
            (voice.name.toLowerCase().includes('google') && voice.name.toLowerCase().includes('us english') && voice.name.toLowerCase().includes('female')) ||
            (!voice.name.toLowerCase().includes('male') && !voice.name.toLowerCase().includes('david') && !voice.name.toLowerCase().includes('aaron') && !voice.name.toLowerCase().includes('daniel')) // Exclude known male names
        );

        // Fallback 1: If no specific female voice in current language, try any female voice from all voices
        if (!selectedVoice) {
            selectedVoice = voices.find(voice =>
                (voice.name.toLowerCase().includes('female') ||
                voice.name.toLowerCase().includes('zira') ||
                voice.name.toLowerCase().includes('sara') ||
                voice.name.toLowerCase().includes('helen')) &&
                !voice.name.toLowerCase().includes('male') && !voice.name.toLowerCase().includes('david') && !voice.name.toLowerCase().includes('aaron') && !voice.name.toLowerCase().includes('daniel')
            );
        }
    }

    // Final fallback: browser default voice, or first available voice if nothing matches
    return selectedVoice || voices.find(voice => voice.default) || (voices.length > 0 ? voices[0] : null);
  }, []);

  // Main audio playback effect
  useEffect(() => {
    let stopAudio = () => {};
    const currentAudioContext = audioContextRef.current; // Capture current ref value for cleanup

    // Initialize AudioContext if not already, and resume it
    const initAndResumeAudioContext = async () => {
      if (!currentAudioContext || currentAudioContext.state === 'closed') {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
        gainNodeRef.current = audioContextRef.current.createGain();
        gainNodeRef.current.connect(audioContextRef.current.destination);
        gainNodeRef.current.gain.value = volumeLevel; // Set initial volume
      }
      if (audioContextRef.current && audioContextRef.current.state === 'suspended') {
        try {
          await audioContextRef.current.resume();
        } catch (e) {
          console.error("AudioContext resume failed on alarm:", e);
        }
      }
    };

    if (reminder.soundType === 'voice') {
       const speak = () => {
           window.speechSynthesis.cancel();
           const tone = reminder.voiceTone || 'normal';
           const gender = reminder.voiceGender || 'female';
           const foodStr = reminder.foodContext.replace('_', ' ');

           let text = '';
           let lang = 'en-US';

           if (tone === 'hindi') {
               text = `Sunneye! Yeh aapki sehat ka sawal hai. Dawai ${reminder.medicineName} lene ka waqt ho gaya hai. Aapko ${reminder.dose} dawai ${foodStr} leni hai. Kripya ise abhi lein. Main phir se keh rahi hoon, dawai ka naam ${reminder.medicineName} hai aur dose ${reminder.dose} hai. Ise turant lein.`;
               lang = 'hi-IN';
           } else if (tone === 'strict') {
               text = `Attention! This is a mandatory health alert. You must ingest ${reminder.dose} of ${reminder.medicineName} immediately. Intake rule is ${foodStr}. Do not ignore this. Repeating: ${reminder.medicineName}, ${reminder.dose}. Take it now.`;
           } else if (tone === 'friendly') {
               text = `Hello! Hope you are feeling better. It's time for your medication. Please take ${reminder.dose} of ${reminder.medicineName} ${foodStr}. Stay healthy and take care! I'll keep reminding you: ${reminder.medicineName} now!`;
           } else {
               text = `Time for your medicine reminder. Medicine name is ${reminder.medicineName}. Dose is ${reminder.dose}. Rule is ${foodStr}. Please confirm you have taken it by pressing the button on your screen. ${reminder.medicineName}, ${reminder.dose}, now.`;
           }

           const utterance = new SpeechSynthesisUtterance(text);
           utterance.lang = lang;

           const setVoiceAndSpeak = () => {
             const selectedVoice = getSpeechVoice(gender, lang);
             if (selectedVoice) {
               utterance.voice = selectedVoice;
             }
             utterance.rate = 0.85; // Slightly slower for absolute clarity
             utterance.pitch = 1.1; // Slightly higher to grab attention
             utterance.volume = volumeLevel; // Apply current volume level
             window.speechSynthesis.speak(utterance);
           };

           if (window.speechSynthesis.getVoices().length === 0) {
             window.speechSynthesis.onvoiceschanged = setVoiceAndSpeak;
           } else {
             setVoiceAndSpeak();
           }
       };

       speak();
       const voiceInterval = setInterval(speak, 10000); 
       stopAudio = () => { clearInterval(voiceInterval); window.speechSynthesis.cancel(); };
    } else if (reminder.soundType === 'custom' && reminder.customSoundData) {
        const audio = new Audio(reminder.customSoundData);
        audio.loop = true;
        audio.volume = volumeLevel; // Apply current volume level
        customAudioRef.current = audio;
        audio.play().catch(e => console.error("Custom audio play failed:", e));
        stopAudio = () => { audio.pause(); audio.currentTime = 0; };
    } else { // Tone sounds
       initAndResumeAudioContext().then(() => {
           const ctx = audioContextRef.current;
           const gainNode = gainNodeRef.current;
           if (!ctx || !gainNode) return; // Should not happen

           const playPattern = () => {
               const playTone = (freq: number, start: number, duration: number, type: OscillatorType = 'sine') => {
                    const osc = ctx.createOscillator();
                    const g = ctx.createGain(); // Use a local gain for smooth attack/decay per tone
                    osc.type = type;
                    osc.frequency.setValueAtTime(freq, ctx.currentTime + start);
                    g.gain.setValueAtTime(0, ctx.currentTime + start);
                    g.gain.linearRampToValueAtTime(1, ctx.currentTime + start + 0.05); // Full volume for the tone
                    g.gain.linearRampToValueAtTime(0, ctx.currentTime + start + duration);
                    osc.connect(g); g.connect(gainNode); // Connect to the main gain node
                    osc.start(ctx.currentTime + start); osc.stop(ctx.currentTime + start + duration);
               };

               if (reminder.soundType === 'soft') playTone(300, 0, 0.5);
               else if (reminder.soundType === 'loud') { playTone(800, 0, 0.3, 'square'); playTone(800, 0.4, 0.3, 'square'); }
               else if (reminder.soundType === 'zen') { playTone(200, 0, 1, 'sine'); playTone(300, 0.5, 1, 'sine'); }
               else if (reminder.soundType === 'emergency') { for(let i=0; i<4; i++) playTone(1200 - (i*100), i*0.15, 0.1, 'sawtooth'); }
               else if (reminder.soundType === 'musical') { playTone(440, 0, 0.2, 'triangle'); playTone(554.37, 0.2, 0.2, 'triangle'); playTone(659.25, 0.4, 0.4, 'triangle'); }
               else if (reminder.soundType === 'ringtone') { for(let i=0; i<3; i++) { playTone(600, i*0.2, 0.1); playTone(800, i*0.2 + 0.1, 0.1); } }
               else playTone(440, 0, 0.3, 'square');
           };
           playPattern(); // Initial play
           const toneInterval = window.setInterval(playPattern, 2000);
           intervalRef.current = toneInterval;
           stopAudio = () => { 
             if (intervalRef.current) clearInterval(intervalRef.current); 
             // Do not close AudioContext here, as it's managed by the modal's lifecycle
           };
       }).catch(e => console.error("Tone playback initialization failed:", e));
    }

    return () => {
      stopAudio(); // Call specific stop function
      if (customAudioRef.current) {
        customAudioRef.current.pause();
        customAudioRef.current.currentTime = 0;
        customAudioRef.current = null;
      }
      if (audioContextRef.current && audioContextRef.current.state === 'running') {
        // Leave AudioContext running if other parts of the app might need it
        // Or if we need to close, ensure it's safe to do so
        // For simplicity, will not close here, let browser manage
      }
    };
  }, [reminder, getSpeechVoice]); 

  // Gradually increase volume & apply to global gain node
  useEffect(() => {
    // Apply initial volume immediately
    if (gainNodeRef.current) gainNodeRef.current.gain.value = volumeLevel;
    if (customAudioRef.current) customAudioRef.current.volume = volumeLevel;

    // Gradual increase interval
    const volInterval = setInterval(() => {
        setVolumeLevel(p => {
            const next = Math.min(p + 0.05, 1.0); // Smaller step for smoother increase
            if (gainNodeRef.current) gainNodeRef.current.gain.value = next;
            if (customAudioRef.current) customAudioRef.current.volume = next;
            if (window.speechSynthesis.speaking) {
                const utterances = window.speechSynthesis.getVoices().map(v => new SpeechSynthesisUtterance("")); // Placeholder, cannot directly modify current utterance volume
                // Can't directly control volume of active SpeechSynthesisUtterance.
                // It's set once on speak(). New utterances will get new volume.
            }
            return next;
        });
    }, 2000); // Check every 2 seconds

    return () => clearInterval(volInterval);
  }, [volumeLevel]); 

  // Helper to close notification
  const closeCurrentNotification = () => {
    if (notificationPermission === 'granted' && 'getNotifications' in ServiceWorkerRegistration.prototype) {
        navigator.serviceWorker.ready.then(registration => {
            registration.getNotifications({ tag: notificationTagRef.current }).then(notifications => {
                notifications.forEach(notification => notification.close());
            });
        }).catch(e => console.error("ServiceWorker registration error for closing notification:", e));
    }
  };

  const handleTake = () => {
    closeCurrentNotification();
    onTake();
  };

  const handleSnooze = (minutes: number) => {
    closeCurrentNotification();
    onSnooze(minutes);
  };

  const handleSkip = () => {
    closeCurrentNotification();
    onSkip();
  };

  return (
    <div className="fixed inset-0 z-[2000] bg-slate-900 flex items-center justify-center p-6">
      <div className="bg-white w-full max-w-sm rounded-[3.5rem] shadow-2xl overflow-hidden text-center relative border border-slate-100 animate-slide-up">
        <div className="bg-rose-600 p-12 flex justify-center relative overflow-hidden">
            <div className="absolute inset-0 bg-gradient-to-br from-rose-500 to-red-800"></div>
            <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-10"></div>
            <div className="relative">
                <div className="absolute inset-0 bg-white rounded-full animate-ping opacity-30"></div>
                <div className="bg-white rounded-[2.5rem] p-8 relative z-10 text-rose-600 shadow-2xl animate-bounce">
                    <svg className="w-14 h-14" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9" /></svg>
                </div>
            </div>
        </div>
        <div className="p-10 space-y-8 bg-white">
            <div className="space-y-2">
                <h4 className="text-[10px] font-black text-rose-500 uppercase tracking-[0.4em]">Time for Medication</h4>
                <h2 className="text-3xl font-black text-slate-900 tracking-tighter leading-none">{reminder.medicineName}</h2>
                <div className="flex justify-center items-center space-x-2">
                    <span className="text-teal-600 font-black text-xl tracking-tight uppercase">{reminder.dose}</span>
                    <span className="w-1.5 h-1.5 bg-slate-200 rounded-full"></span>
                    <span className="text-slate-400 font-black text-xs uppercase tracking-widest">{reminder.foodContext.replace('_', ' ')}</span>
                </div>
            </div>

            <div className="space-y-4">
                <button onClick={handleTake} className="w-full bg-slate-900 text-white py-6 rounded-[2.5rem] font-black text-lg shadow-2xl hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center space-x-3">
                    <span>💊 I Have Taken It</span>
                </button>
                <div className="grid grid-cols-2 gap-4">
                    <button onClick={() => handleSnooze(10)} className="bg-slate-50 text-slate-500 py-5 rounded-3xl font-black text-[10px] uppercase tracking-widest hover:bg-slate-100 border border-slate-100">Snooze 10m</button>
                    <button onClick={() => handleSnooze(30)} className="bg-slate-50 text-slate-500 py-5 rounded-3xl font-black text-[10px] uppercase tracking-widest hover:bg-slate-100 border border-slate-100">Snooze 30m</button>
                </div>
            </div>

            <div className="pt-2">
                 <p className="text-[8px] font-black text-slate-300 uppercase tracking-[0.3em]">AI Voice Assistant is Active</p>
            </div>
        </div>
      </div>
    </div>
  );
};

