import React, { useState, useRef, useEffect } from 'react';
import QRCode from 'qrcode';

interface EmergencyWallpaperProps {
  onBack: () => void;
  userDisplayName?: string;
}

const EmergencyWallpaper: React.FC<EmergencyWallpaperProps> = ({ onBack, userDisplayName }) => {
  const [name, setName] = useState(userDisplayName || '');
  const [bloodGroup, setBloodGroup] = useState('');
  const [emergencyNumber, setEmergencyNumber] = useState('');
  const [allergies, setAllergies] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [wallpaperUrl, setWallpaperUrl] = useState<string | null>(null);

  const canvasRef = useRef<HTMLCanvasElement>(null);

  const generateWallpaper = async () => {
    if (!name || !emergencyNumber) {
        alert("Please enter at least your Name and an Emergency Contact Number.");
        return;
    }
    setIsGenerating(true);

    try {
        const canvas = canvasRef.current;
        if (!canvas) return;

        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        // 1. Setup Canvas (1080x1920 HD)
        canvas.width = 1080;
        canvas.height = 1920;

        // 2. Background (Dark Tech Gradient for readability)
        const gradient = ctx.createLinearGradient(0, 0, 0, 1920);
        gradient.addColorStop(0, '#0f172a'); // Slate 900
        gradient.addColorStop(1, '#000000'); // Black
        ctx.fillStyle = gradient;
        ctx.fillRect(0, 0, 1080, 1920);

        // 3. Header
        ctx.fillStyle = '#ef4444'; // Red 500
        ctx.font = 'bold 80px "Plus Jakarta Sans", sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText('EMERGENCY', 540, 300);

        ctx.fillStyle = '#ffffff';
        ctx.font = '60px "Plus Jakarta Sans", sans-serif';
        ctx.fillText('MEDICAL INFO', 540, 380);

        // 4. Generate QR Code
        const qrData = `EMERGENCY INFO:\nName: ${name}\nBlood: ${bloodGroup || 'N/A'}\nICE: ${emergencyNumber}\nNotes: ${allergies || 'None'}`;
        const qrDataUrl = await QRCode.toDataURL(qrData, { 
            width: 600,
            margin: 2,
            color: {
                dark: '#000000',
                light: '#ffffff'
            }
        });

        // 5. Draw QR Image
        const qrImg = new Image();
        qrImg.src = qrDataUrl;
        await new Promise((resolve) => {
            qrImg.onload = () => {
                // Draw white background for QR
                ctx.fillStyle = '#ffffff';
                ctx.fillRect(240, 580, 600, 600);
                // Draw QR
                ctx.drawImage(qrImg, 240, 580, 600, 600);

                // Add "Scan Me" border
                ctx.strokeStyle = '#ef4444';
                ctx.lineWidth = 10;
                ctx.strokeRect(230, 570, 620, 620);

                resolve(null);
            };
        });

        // 6. Draw Text Details (Human Readable)
        ctx.fillStyle = '#ffffff';
        ctx.font = 'bold 50px "Plus Jakarta Sans", sans-serif';
        ctx.textAlign = 'center';

        let yPos = 1350;
        ctx.fillStyle = '#94a3b8'; // Slate 400 label
        ctx.font = '40px "Plus Jakarta Sans", sans-serif';
        ctx.fillText('Name', 540, yPos);

        ctx.fillStyle = '#ffffff'; // Value
        ctx.font = 'bold 60px "Plus Jakarta Sans", sans-serif';
        ctx.fillText(name.toUpperCase(), 540, yPos + 60);

        yPos += 180;
        ctx.fillStyle = '#94a3b8';
        ctx.font = '40px "Plus Jakarta Sans", sans-serif';
        ctx.fillText('Emergency Contact (ICE)', 540, yPos);

        ctx.fillStyle = '#ef4444'; // Red for number
        ctx.font = 'bold 80px "Plus Jakarta Sans", sans-serif';
        ctx.fillText(emergencyNumber, 540, yPos + 80);

        if (bloodGroup) {
            yPos += 180;
            ctx.fillStyle = '#94a3b8';
            ctx.font = '40px "Plus Jakarta Sans", sans-serif';
            ctx.fillText('Blood Group', 540, yPos);

            ctx.fillStyle = '#ffffff';
            ctx.font = 'bold 60px "Plus Jakarta Sans", sans-serif';
            ctx.fillText(bloodGroup.toUpperCase(), 540, yPos + 60);
        }

        // 7. Footer
        ctx.fillStyle = '#334155';
        ctx.font = '30px "Plus Jakarta Sans", sans-serif';
        ctx.fillText('Generated by MediIQ AI', 540, 1850);

        setWallpaperUrl(canvas.toDataURL('image/png'));
    } catch (e) {
        console.error("Wallpaper generation failed", e);
        alert("Could not generate wallpaper. Please try again.");
    } finally {
        setIsGenerating(false);
    }
  };

  const handleDownload = () => {
    if (wallpaperUrl) {
        const link = document.createElement('a');
        link.download = `MediIQ_Emergency_Wallpaper_${name}.png`;
        link.href = wallpaperUrl;
        link.click();
    }
  };

  return (
    <div className="bg-slate-50 min-h-screen animate-fade-in pb-20">
      <div className="p-6">
        <button onClick={onBack} className="flex items-center text-slate-500 font-bold mb-6 hover:text-slate-800 transition-colors">
            <svg className="w-5 h-5 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg>
            Back
        </button>

        <h2 className="text-3xl font-extrabold text-slate-900 tracking-tight mb-2">Life Saver Wallpaper</h2>
        <p className="text-slate-500 text-sm mb-8">Create a lock screen wallpaper. If you are in an accident, rescuers can scan it to call your family.</p>

        {!wallpaperUrl ? (
            <div className="bg-white p-6 rounded-[2rem] shadow-xl border border-slate-100 space-y-6 animate-slide-up">
                <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Your Name</label>
                    <input type="text" value={name} onChange={e => setName(e.target.value)} placeholder="Full Name" className="w-full bg-slate-50 p-4 rounded-xl border border-slate-100 font-bold text-slate-900" />
                </div>

                <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Blood Group</label>
                        <select value={bloodGroup} onChange={e => setBloodGroup(e.target.value)} className="w-full bg-slate-50 p-4 rounded-xl border border-slate-100 font-bold text-slate-900">
                            <option value="">Select</option>
                            <option value="A+">A+</option><option value="A-">A-</option>
                            <option value="B+">B+</option><option value="B-">B-</option>
                            <option value="O+">O+</option><option value="O-">O-</option>
                            <option value="AB+">AB+</option><option value="AB-">AB-</option>
                        </select>
                    </div>
                    <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Emergency No.</label>
                        <input type="tel" value={emergencyNumber} onChange={e => setEmergencyNumber(e.target.value)} placeholder="Parent/Spouse" className="w-full bg-rose-50 p-4 rounded-xl border border-rose-100 font-bold text-rose-600 placeholder-rose-300" />
                    </div>
                </div>

                <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Allergies / Conditions</label>
                    <textarea value={allergies} onChange={e => setAllergies(e.target.value)} placeholder="e.g. Diabetic, Penicillin Allergy" className="w-full bg-slate-50 p-4 rounded-xl border border-slate-100 font-bold text-slate-900 h-24 resize-none" />
                </div>

                <button 
                    onClick={generateWallpaper}
                    disabled={isGenerating}
                    className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-sm uppercase tracking-widest shadow-lg hover:scale-[1.02] active:scale-95 transition-all flex justify-center items-center"
                >
                    {isGenerating ? 'Generating...' : 'Create Magic Wallpaper ✨'}
                </button>
            </div>
        ) : (
            <div className="animate-fade-in flex flex-col items-center">
                 <div className="relative w-64 h-[28rem] rounded-[2rem] overflow-hidden shadow-2xl border-4 border-slate-900 mb-8 bg-slate-900">
                    <img src={wallpaperUrl} alt="Wallpaper Preview" className="w-full h-full object-cover" />
                 </div>

                 <div className="w-full max-w-sm space-y-3">
                     <button onClick={handleDownload} className="w-full bg-teal-600 text-white py-5 rounded-2xl font-black text-sm uppercase tracking-widest shadow-lg shadow-teal-600/30 hover:scale-[1.02] active:scale-95 transition-all">
                        Download Image 📥
                     </button>
                     <button onClick={() => setWallpaperUrl(null)} className="w-full bg-white text-slate-500 py-4 rounded-2xl font-bold text-xs uppercase tracking-widest border border-slate-200">
                        Edit Details
                     </button>
                 </div>

                 <p className="mt-6 text-xs text-slate-400 text-center max-w-xs">
                     <strong>Tip:</strong> Set this image as your "Lock Screen" so it is visible without unlocking your phone.
                 </p>
            </div>
        )}

        {/* Hidden Canvas for generation */}
        <canvas ref={canvasRef} className="hidden"></canvas>
      </div>
    </div>
  );
};

export default EmergencyWallpaper;

import React, { useState, useEffect, useCallback } from 'react';
import Scanner from './components/Scanner.tsx';
import MedicineResult from './components/MedicineResult.tsx';
import Reminders from './components/Reminders.tsx';
import History from './components/History.tsx';
import DoctorAI from './components/DoctorAI.tsx';
import PremiumModal from './components/PremiumModal.tsx';
import Profile from './components/Profile.tsx';
import LegalAndHelp from './components/LegalAndHelp.tsx';
import AlarmRingingModal from './components/AlarmRingingModal.tsx';
import IntroFlow from './components/IntroFlow.tsx';
import LoginScreen from './components/LoginScreen.tsx';
import ExpiryCabinet from './components/ExpiryCabinet.tsx';
import EmergencyWallpaper from './components/EmergencyWallpaper.tsx';
import { MedicineData, AppView, Reminder, PatientProfile, ScanHistoryItem, FamilyMember, User, CabinetItem } from './types.ts';
import { getHealthTip } from './services/geminiService.ts';
import { subscribeToAuthChanges, loginWithGoogle, logout, handleRedirectResult } from './services/authService.ts';

const App: React.FC = () => {
  // -- Auth State --
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isGuest, setIsGuest] = useState<boolean>(() => localStorage.getItem('mediScan_is_guest') === 'true');
  const [authChecked, setAuthChecked] = useState(false);
  const [showIntro, setShowIntro] = useState<boolean>(true);

  // -- Data State (Initialized Empty, Loaded via Effect) --
  const [reminders, setReminders] = useState<Reminder[]>([]);
  const [scanHistory, setScanHistory] = useState<ScanHistoryItem[]>([]);
  const [familyMembers, setFamilyMembers] = useState<FamilyMember[]>([]);
  const [cabinetItems, setCabinetItems] = useState<CabinetItem[]>([]);
  const [isPremium, setIsPremium] = useState<boolean>(false);

  // -- UI State --
  const [currentView, setCurrentView] = useState<AppView>(AppView.HOME);
  const [scannedData, setScannedData] = useState<MedicineData | null>(null);
  const [patientProfile, setPatientProfile] = useState<PatientProfile | undefined>(undefined);
  const [showPremiumModal, setShowPremiumModal] = useState(false);
  const [healthTip, setHealthTip] = useState<string>("");
  const [isPreviouslyScanned, setIsPreviouslyScanned] = useState(false);
  const [overdoseWarning, setOverdoseWarning] = useState(false);
  const [activeAlarm, setActiveAlarm] = useState<Reminder | null>(null);
  const [notificationPermission, setNotificationPermission] = useState<NotificationPermission>(() => Notification.permission);
  const [isLoadingData, setIsLoadingData] = useState(true);

  // Helper: Generate Storage Key based on User
  // Guests use legacy keys (no prefix) to preserve existing data.
  // Logged-in users use `mediScan_UID_` prefix.
  const getStorageKey = useCallback((baseKey: string) => {
    if (currentUser) {
      return `mediScan_${currentUser.uid}_${baseKey}`;
    }
    return `mediScan_${baseKey}`;
  }, [currentUser]);

  // -- Initialization & Auth --
  useEffect(() => {
    // 1. Check Intro
    const introSeen = localStorage.getItem('mediScan_intro_seen');
    if (introSeen) setShowIntro(false);

    // 2. Handle Redirect Result (Important for Mobile Login)
    handleRedirectResult().catch((error) => {
        console.error("Redirect Error:", error);
    });

    // 3. Auth Subscription
    const unsubscribe = subscribeToAuthChanges((user) => {
      setCurrentUser(user);
      setAuthChecked(true);
      if (user) {
          setIsGuest(false);
          localStorage.removeItem('mediScan_is_guest');
      }
    });

    // 4. Health Tip & Device ID
    if (!localStorage.getItem('mediScan_deviceId')) {
        localStorage.setItem('mediScan_deviceId', crypto.randomUUID());
    }
    getHealthTip().then(setHealthTip).catch(() => setHealthTip("Always verify medicine with a doctor."));

    return () => unsubscribe();
  }, []);

  // -- Load Data when User Changes --
  useEffect(() => {
    if (!authChecked) return;
    if (!currentUser && !isGuest) return; // Wait for login choice

    setIsLoadingData(true);

    // Load Reminders
    try {
        const saved = localStorage.getItem(getStorageKey('reminders'));
        setReminders(saved ? JSON.parse(saved) : []);
    } catch { setReminders([]); }

    // Load History
    try {
        const saved = localStorage.getItem(getStorageKey('history'));
        setScanHistory(saved ? JSON.parse(saved) : []);
    } catch { setScanHistory([]); }

    // Load Family
    try {
        const saved = localStorage.getItem(getStorageKey('family'));
        if (saved) {
            setFamilyMembers(JSON.parse(saved));
        } else {
            // Default Profile
            const defaultMe: FamilyMember = {
                id: 'me',
                name: currentUser?.displayName || 'Me',
                ageGroup: 'adult',
                gender: 'male',
                isPregnant: false,
                isBreastfeeding: false,
                language: 'english',
                avatar: currentUser?.photoURL ? '📸' : '🧑‍💻'
            };
            setFamilyMembers([defaultMe]);
        }
    } catch { setFamilyMembers([]); }

    // Load Cabinet
    try {
        const saved = localStorage.getItem(getStorageKey('cabinet'));
        setCabinetItems(saved ? JSON.parse(saved) : []);
    } catch { setCabinetItems([]); }

    // Load Premium
    try {
        const saved = localStorage.getItem(getStorageKey('premium'));
        setIsPremium(saved === 'true');
    } catch { setIsPremium(false); }

    setIsLoadingData(false);

  }, [currentUser, isGuest, authChecked, getStorageKey]);

  // -- Save Data Effects (Triggered on State Change) --
  useEffect(() => {
    if (isLoadingData) return;
    localStorage.setItem(getStorageKey('reminders'), JSON.stringify(reminders));
  }, [reminders, getStorageKey, isLoadingData]);

  useEffect(() => {
    if (isLoadingData) return;
    localStorage.setItem(getStorageKey('history'), JSON.stringify(scanHistory));
  }, [scanHistory, getStorageKey, isLoadingData]);

  useEffect(() => {
    if (isLoadingData) return;
    localStorage.setItem(getStorageKey('family'), JSON.stringify(familyMembers));
  }, [familyMembers, getStorageKey, isLoadingData]);

  useEffect(() => {
    if (isLoadingData) return;
    localStorage.setItem(getStorageKey('cabinet'), JSON.stringify(cabinetItems));
  }, [cabinetItems, getStorageKey, isLoadingData]);

  useEffect(() => {
    if (isLoadingData) return;
    localStorage.setItem(getStorageKey('premium'), String(isPremium));
  }, [isPremium, getStorageKey, isLoadingData]);


  // -- Alarm Checker & Expiry Notification --
  useEffect(() => {
    // 1. Alarm Check
    const interval = setInterval(() => {
        const now = new Date();
        const currentTime = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;

        const triggered = reminders.find(r => r.active && r.time === currentTime && (!r.snoozedUntil || Date.now() >= r.snoozedUntil));
        if (triggered && !activeAlarm) {
            setActiveAlarm(triggered);
        }
    }, 10000); 

    // 2. Expiry Check (Run once on load or when cabinet changes)
    if (cabinetItems.length > 0 && notificationPermission === 'granted') {
        const now = new Date();
        cabinetItems.forEach(item => {
            const expiry = new Date(item.expiryDate);
            const diffTime = expiry.getTime() - now.getTime();
            const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

            // Notification logic for expiring meds (7 days or less)
            if (diffDays <= 7 && diffDays >= -1) {
                 const noteTitle = diffDays < 0 ? `⚠️ EXPIRED: ${item.medicineName}` : `⚠️ Expiry Alert: ${item.medicineName}`;
                 const noteBody = diffDays < 0 ? "Throw it away! This medicine has become poison." : `Expires in ${diffDays} days. Plan to dispose of it soon.`;

                 // Debounce check using session storage to avoid spamming on refresh (one alert per day per item)
                 const key = `expiry_alert_${item.id}_${now.toDateString()}`;
                 if (!sessionStorage.getItem(key)) {
                    new Notification(noteTitle, {
                        body: noteBody,
                        icon: '/favicon.png'
                    });
                    sessionStorage.setItem(key, 'sent');
                 }
            }
        });
    }

    return () => clearInterval(interval);
  }, [reminders, activeAlarm, cabinetItems, notificationPermission]);

  // -- Handlers --

  const requestNotificationPermission = async () => {
    if (Notification.permission === 'default') {
      const permission = await Notification.requestPermission();
      setNotificationPermission(permission);
    }
  };

  const handleUpgrade = async (txnId?: string) => {
    setIsPremium(true);
    if (txnId) localStorage.setItem(getStorageKey('txnId'), txnId);
    setShowPremiumModal(false);
    setCurrentView(AppView.PROFILE);
  };

  const handleLogin = async () => {
    try {
        await loginWithGoogle();
    } catch (error) {
        alert("Login initiation failed. Please try again.");
    }
  };

  const handleGuestContinue = () => {
      setIsGuest(true);
      localStorage.setItem('mediScan_is_guest', 'true');
  };

  const handleLogout = async () => {
    try {
        await logout();
        setIsGuest(false);
        setScannedData(null);
        setCurrentView(AppView.HOME);
        localStorage.removeItem('mediScan_is_guest');
    } catch (error) {
        console.error("Logout failed", error);
    }
  };

  const addReminder = (r: Reminder) => setReminders(prev => [...prev, r]);
  const deleteReminder = (id: string) => setReminders(prev => prev.filter(r => r.id !== id));
  const toggleReminder = (id: string) => setReminders(prev => prev.map(r => r.id === id ? { ...r, active: !r.active } : r));
  const updateReminder = (updated: Reminder) => setReminders(prev => prev.map(r => r.id === updated.id ? updated : r));

  const addCabinetItem = (item: CabinetItem) => setCabinetItems(prev => [...prev, item]);
  const deleteCabinetItem = (id: string) => setCabinetItems(prev => prev.filter(i => i.id !== id));
  const clearExpiredCabinet = () => {
      const now = new Date();
      setCabinetItems(prev => prev.filter(i => new Date(i.expiryDate) >= now));
  };

  const handleScanComplete = (data: MedicineData, profile: PatientProfile) => {
    const now = Date.now();
    const fourHours = 4 * 60 * 60 * 1000;
    const recentScan = scanHistory.find(item => {
        const isSameMed = item.medicineName.toLowerCase().trim() === data.name.toLowerCase().trim();
        const isRecent = (now - item.timestamp) < fourHours;
        return isSameMed && isRecent;
    });
    setIsPreviouslyScanned(scanHistory.some(item => item.medicineName.toLowerCase().trim() === data.name.toLowerCase().trim()));
    setOverdoseWarning(!!recentScan);
    setScanHistory(prev => [{ id: crypto.randomUUID(), timestamp: now, medicineName: data.name, data }, ...prev].slice(0, 20));
    setScannedData(data);
    setPatientProfile(profile);
  };

  const handleIntroComplete = () => {
    localStorage.setItem('mediScan_intro_seen', 'true');
    setShowIntro(false);
  };

  // -- Render Flow --

  if (showIntro) {
    return <IntroFlow onComplete={handleIntroComplete} />;
  }

  if (authChecked && !currentUser && !isGuest) {
      return <LoginScreen onLogin={handleLogin} onGuest={handleGuestContinue} />;
  }

  const renderContent = () => {
    if (scannedData) {
      return (
        <MedicineResult 
          data={scannedData} 
          profile={patientProfile} 
          isPremium={isPremium} 
          isPreviouslyScanned={isPreviouslyScanned} 
          overdoseWarning={overdoseWarning} 
          onOpenPremium={() => setShowPremiumModal(true)} 
          onClose={() => setScannedData(null)}
          onAddReminder={(rem) => {
            addReminder(rem);
            setCurrentView(AppView.REMINDERS);
            setScannedData(null);
          }}
          onAddToCabinet={(item) => {
              addCabinetItem(item);
          }}
        />
      );
    }

    switch (currentView) {
      case AppView.HOME:
      case AppView.SCANNER:
        return (
          <div className="bg-slate-50 min-h-screen">
