export const getDoctorAIResponse = async (history: ChatMessage[]): Promise<string> => {
  try {
    const contents = history.map(msg => ({
      role: msg.role === 'user' ? 'user' : 'model',
      parts: [{ text: msg.content }]
    }));

    try {
        const response = await ai.models.generateContent({
            model: "gemini-3-pro-preview",
            contents: contents,
            config: {
                systemInstruction: "You are 'MediIQ Doctor AI', a professional and empathetic medical assistant. Help users understand symptoms, health conditions, and wellness. ALWAYS include a disclaimer that you are an AI and not a real doctor. If symptoms sound severe, strongly advise visiting an Emergency Room immediately. Keep responses concise and structured with bullet points where appropriate."
            }
        });
        return response.text || "I apologize, I'm having trouble processing that right now.";
    } catch (error: any) {
        const errorMsg = JSON.stringify(error);
        console.warn("Gemini Pro failed, failing back to Flash:", errorMsg);

        if (errorMsg.includes("429") || errorMsg.includes("quota")) {
             return "I'm currently receiving too many requests. Please try again in a few minutes.";
        }

        try {
            const response = await ai.models.generateContent({
                model: "gemini-3-flash-preview",
                contents: contents,
                config: {
                    systemInstruction: "You are 'MediIQ Doctor AI'. Be concise and helpful. Disclaimer: I am an AI, not a doctor."
                }
            });
            return response.text || "I'm currently unable to assist. Please try again later.";
        } catch (fallbackError) {
             const fbMsg = JSON.stringify(fallbackError);
             if (fbMsg.includes("429") || fbMsg.includes("quota")) {
                 return "Server usage limit reached. Please come back tomorrow.";
             }
             return "I am currently unavailable due to technical issues.";
        }
    }
  } catch (error) {
    console.error("Doctor AI Error:", error);
    return "I'm currently unable to assist due to a connection issue. If this is an emergency, please call local medical services immediately.";
  }
};

import React, { useState, useRef } from 'react';
import { analyzeSkinCondition } from '../services/geminiService';
import { DermaData } from '../types';

interface DermaScannerProps {
  onBack: () => void;
}

const DermaScanner: React.FC<DermaScannerProps> = ({ onBack }) => {
  const [image, setImage] = useState<string | null>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const [result, setResult] = useState<DermaData | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const cameraInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const startAnalysis = async () => {
    if (!image) return;
    setAnalyzing(true);
    try {
      const data = await analyzeSkinCondition(image);
      setResult(data);
    } catch (error) {
      alert("Failed to analyze skin condition. Please ensure the image is clear.");
    } finally {
      setAnalyzing(false);
    }
  };

  const getSeverityColor = (sev: string) => {
    switch (sev) {
      case 'Severe': return 'bg-rose-500 text-white';
      case 'Moderate': return 'bg-orange-400 text-white';
      default: return 'bg-teal-500 text-white';
    }
  };

  if (result) {
    return (
      <div className="min-h-screen bg-slate-50 pb-24 animate-fade-in relative z-50">
         <div className="sticky top-0 z-40 bg-white/80 backdrop-blur-md px-6 py-4 flex items-center justify-between border-b border-slate-100">
             <button onClick={() => setResult(null)} className="flex items-center text-slate-500 font-bold">
                <svg className="w-5 h-5 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg>
                Rescan
             </button>
             <h2 className="text-lg font-black text-violet-600 tracking-tight">Derma-Scan Report</h2>
         </div>

         <div className="p-6 space-y-6">
