export const getDoctorAIResponse = async (history: ChatMessage[], scanHistory?: ScanHistoryItem[]): Promise<string> => {
  try {
    // RAG Logic: Summarize the scan history into context
    let contextData = "";
    if (scanHistory && scanHistory.length > 0) {
        const historySummary = scanHistory.slice(0, 10).map(item => {
            const date = new Date(item.timestamp).toLocaleDateString();
            return `- [${date}] Scanned: ${item.medicineName}. Risk: ${item.data.riskScore}. Purpose: ${item.data.uses.join(', ')}.`;
        }).join('\n');

        contextData = `
        CONTEXT: You have access to the user's recent medical scan history (Medicines/Reports). 
        Use this to answer questions about past conditions, comparisons, or drug interactions.
        USER HISTORY:
        ${historySummary}

        If the user asks "Has my sugar increased?", check if there are diabetes medicines or reports in the history and compare them.
        If the user asks about interactions, check the medicines in the history.
        `;
    }

    const contents = history.map(msg => ({
      role: msg.role === 'user' ? 'user' : 'model',
      parts: [{ text: msg.content }]
    }));

    const systemInstruction = `You are 'MediIQ Doctor AI', a professional and empathetic medical assistant. 
    ${contextData}
    Help users understand symptoms, health conditions, and wellness. 
    ALWAYS include a disclaimer that you are an AI and not a real doctor. 
    If symptoms sound severe, strongly advise visiting an Emergency Room immediately. 
    Keep responses concise and structured with bullet points where appropriate.`;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-3-pro-preview",
            contents: contents,
            config: {
                systemInstruction: systemInstruction
            }
        });
        return response.text || "I apologize, I'm having trouble processing that right now.";
    } catch (error: any) {
        const errorMsg = JSON.stringify(error);
        console.warn("Gemini Pro failed, failing back to Flash:", errorMsg);

        if (errorMsg.includes("429") || errorMsg.includes("quota")) {
             return "I'm currently receiving too many requests. Please try again in a few minutes.";
        }

        try {
            const response = await ai.models.generateContent({
                model: "gemini-3-flash-preview",
                contents: contents,
                config: {
                    systemInstruction: systemInstruction
                }
            });
            return response.text || "I'm currently unable to assist. Please try again later.";
        } catch (fallbackError) {
             const fbMsg = JSON.stringify(fallbackError);
             if (fbMsg.includes("429") || fbMsg.includes("quota")) {
                 return "Server usage limit reached. Please come back tomorrow.";
             }
             return "I am currently unavailable due to technical issues.";
        }
    }
  } catch (error) {
    console.error("Doctor AI Error:", error);
    return "I'm currently unable to assist due to a connection issue. If this is an emergency, please call local medical services immediately.";
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { ChatMessage, ScanHistoryItem } from '../types.ts';
import { getDoctorAIResponse } from '../services/geminiService.ts';

interface DoctorAIProps {
  isPremium: boolean;
  onOpenPremium: () => void;
  userId: string;
}

// Type definition for Web Speech API
declare global {
  interface Window {
    webkitSpeechRecognition: any;
    SpeechRecognition: any;
  }
}

const DoctorAI: React.FC<DoctorAIProps> = ({ isPremium, onOpenPremium, userId }) => {
  // Helper to get scoped keys
  const getChatKey = () => userId === 'guest' ? 'mediIQ_chat_history' : `mediIQ_${userId}_chat_history`;
  const getUsageKey = () => userId === 'guest' ? 'mediIQ_daily_chat_usage' : `mediIQ_${userId}_daily_chat_usage`;

  // Helper to get history key (logic matched with App.tsx)
  const getHistoryKey = () => userId === 'guest' ? 'mediScan_history' : `mediScan_${userId}_history`;

  const [messages, setMessages] = useState<ChatMessage[]>(() => {
    try {
      const saved = localStorage.getItem(getChatKey());
      if (saved) return JSON.parse(saved);
    } catch (e) {
      console.error("Failed to load chat history", e);
    }
    return [
      {
        id: 'welcome',
        role: 'assistant' as const,
        content: 'Hello! I am your MediIQ Doctor AI. I can access your scan history to give you better advice. How can I help you today?',
        timestamp: Date.now()
      }
    ];
  });

  const [scanHistory, setScanHistory] = useState<ScanHistoryItem[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const recognitionRef = useRef<any>(null);

  const [usage, setUsage] = useState(() => {
    const today = new Date().toISOString().split('T')[0];
    const saved = localStorage.getItem(getUsageKey());
    if (saved) {
      const parsed = JSON.parse(saved);
      if (parsed.date === today) return parsed.count;
    }
    return 0;
  });

  // Load Scan History for RAG
  useEffect(() => {
      try {
          const savedHistory = localStorage.getItem(getHistoryKey());
          if (savedHistory) {
              const parsed = JSON.parse(savedHistory);
              // Sort by date desc
              setScanHistory(parsed.sort((a: any, b: any) => b.timestamp - a.timestamp));
          }
      } catch (e) {
          console.error("Failed to load scan history for Doctor AI", e);
      }
  }, [userId]);

  // Reload history when User ID changes (e.g. login/logout)
  useEffect(() => {
    try {
      const saved = localStorage.getItem(getChatKey());
      if (saved) {
        setMessages(JSON.parse(saved));
      } else {
        // Reset to welcome if no history found for this user
        setMessages([{
          id: 'welcome',
          role: 'assistant' as const,
          content: 'Hello! I am your MediIQ Doctor AI. I can access your scan history to give you better advice. How can I help you today?',
          timestamp: Date.now()
        }]);
      }

      const today = new Date().toISOString().split('T')[0];
      const savedUsage = localStorage.getItem(getUsageKey());
      if (savedUsage) {
          const parsed = JSON.parse(savedUsage);
          setUsage(parsed.date === today ? parsed.count : 0);
      } else {
          setUsage(0);
      }
    } catch(e) { console.error(e); }
  }, [userId]);

  const scrollRef = useRef<HTMLDivElement>(null);
  const MAX_FREE_MESSAGES = 10;
  const isLimitReached = !isPremium && usage >= MAX_FREE_MESSAGES;

  useEffect(() => {
    localStorage.setItem(getChatKey(), JSON.stringify(messages));
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, userId]);

  useEffect(() => {
    const today = new Date().toISOString().split('T')[0];
    localStorage.setItem(getUsageKey(), JSON.stringify({ date: today, count: usage }));
  }, [usage, userId]);

  // Cleanup speech recognition on unmount
  useEffect(() => {
    return () => {
      if (recognitionRef.current) {
        recognitionRef.current.stop();
      }
    };
  }, []);

  const handleVoiceInput = () => {
    if (isListening) {
      recognitionRef.current?.stop();
      return;
    }

    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Voice input is not supported in this browser. Please use Chrome or Safari.");
      return;
    }

    const recognition = new SpeechRecognition();
    recognitionRef.current = recognition;
    recognition.lang = 'en-US'; // Could map to profile.language later
    recognition.interimResults = false;
    recognition.maxAlternatives = 1;

    recognition.onstart = () => setIsListening(true);

    recognition.onend = () => {
      setIsListening(false);
      recognitionRef.current = null;
    };

    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      if (transcript) {
        setInput(prev => {
          const trimmed = prev.trim();
          return trimmed ? `${trimmed} ${transcript}` : transcript;
        });
      }
    };

    recognition.onerror = (event: any) => {
      console.error("Speech recognition error", event.error);
      setIsListening(false);
    };

    try {
      recognition.start();
    } catch (e) {
      console.error("Failed to start recognition", e);
    }
  };

  const handleSend = async (text: string) => {
    if (!text.trim() || isLoading || isLimitReached) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user' as const,
      content: text,
      timestamp: Date.now()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);
    if (!isPremium) setUsage(prev => prev + 1);

    try {
      // PASSING SCAN HISTORY HERE FOR RAG
      const responseText = await getDoctorAIResponse([...messages, userMsg], scanHistory);
      const assistantMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'assistant' as const,
        content: responseText,
        timestamp: Date.now()
      };
      setMessages(prev => [...prev, assistantMsg]);
    } catch (error) {
      console.error("Chat error", error);
    } finally {
      setIsLoading(false);
    }
  };

  const clearChat = () => {
    if (confirm("Clear all chat history?")) {
      const welcome: ChatMessage = {
        id: 'welcome',
        role: 'assistant' as const,
        content: 'Hello! I am your MediIQ Doctor AI. I can access your scan history to give you better advice. How can I help you today?',
        timestamp: Date.now()
      };
      setMessages([welcome]);
      localStorage.removeItem(getChatKey());
    }
  };

  const quickPrompts = [
    "Check my history for conflicts",
    "Should I take Advil for headache?",
    "Healthy breakfast tips",
    "How to treat a burn?"
  ];

  return (
    <div className="flex flex-col h-screen max-w-lg mx-auto bg-slate-50 relative overflow-hidden">
      <header className="p-6 pt-10 bg-white border-b border-slate-100 shrink-0 relative z-[60] shadow-sm">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-3">
             <div className="w-12 h-12 bg-indigo-600 rounded-2xl flex items-center justify-center text-2xl shadow-lg shadow-indigo-100 relative">
               👨‍⚕️
               {scanHistory.length > 0 && (
                   <span className="absolute -bottom-1 -right-1 w-4 h-4 bg-teal-500 rounded-full border-2 border-white animate-pulse" title="Connected to Scan History"></span>
               )}
             </div>
             <div>
               <h2 className="text-xl font-black text-slate-900 tracking-tight leading-none mb-1">Doctor AI</h2>
               <div className="flex items-center space-x-2">
                 {scanHistory.length > 0 ? (
